  "Remove": { "es": "Quitar", "pt-BR": "Remover" },
  "Saved. It never touches disk.": { "es": "Guardada. Nunca toca el disco.", "pt-BR": "Salva. Ela nunca toca o disco." },
  "Key removed.": { "es": "Clave eliminada.", "pt-BR": "Chave removida." },
