  "You are on the latest version.": { "es": "Ya tienes la última versión.", "pt-BR": "Você já está na versão mais recente." },
  "That needs to start with http:// or https://.": { "es": "Eso tiene que empezar por http:// o https://.", "pt-BR": "Isso precisa começar com http:// ou https://." },
  "Saved. The new page is loaded next time Notchy starts.": { "es": "Guardado. La nueva página se carga la próxima vez que arranque Notchy.", "pt-BR": "Salvo. A página nova é carregada na próxima vez que o Notchy abrir." },
